export function init_ov_rogue_symbols() {
    let i;

    for (
        i = 0;
        i < (((0) + NHC.MAXPCHARS + NHC.MAXOCLASSES + NHC.MAXMCLASSES + 6 + NHC.MAXOTHER) | 0);
        i++
    )
        cptr.st1o2(go, i, 1, $instance_globals_o_ov_rogue_syms, 0);
}

