/** C ref: symbols.c:319 — @param {CInt} which_set @param {CInt} name_too */
export function clear_symsetentry(which_set, name_too) {
    let other_set = (which_set == NHC.PRIMARYSET) ? NHC.ROGUESET : NHC.PRIMARYSET;
    let old_handling = cptr.ldI32o2(
        gs,
        which_set,
        $sizeof_symsetentry,
        $instance_globals_s_symset + $symsetentry_handling
    );

    if (cptr.ldPtro2(
        gs,
        which_set,
        $sizeof_symsetentry,
        $instance_globals_s_symset + $symsetentry_desc
    ))
        cptr.free(cptr.ldPtro2(
            gs,
            which_set,
            $sizeof_symsetentry,
            $instance_globals_s_symset + $symsetentry_desc
        ));
    cptr.stPtro2(
        gs,
        which_set,
        $sizeof_symsetentry,
        $instance_globals_s_symset + $symsetentry_desc,
        null
    );

    cptr.stI32o2(
        gs,
        which_set,
        $sizeof_symsetentry,
        $instance_globals_s_symset + $symsetentry_handling,
        NHC.H_UNK
    );
    cptr.stI32o2(
        gs,
        which_set,
        $sizeof_symsetentry,
        $instance_globals_s_symset + $symsetentry_nocolor,
        0
    );
    /* initialize restriction bits */
    cptr.stI32o2(
        gs,
        which_set,
        $sizeof_symsetentry,
        $instance_globals_s_symset + $symsetentry_primary,
        0
    );
    cptr.stI32o2(
        gs,
        which_set,
        $sizeof_symsetentry,
        $instance_globals_s_symset + $symsetentry_rogue,
        0
    );

    if (name_too) {
        if (cptr.ldPtro2(
            gs,
            which_set,
            $sizeof_symsetentry,
            $instance_globals_s_symset + $symsetentry_name
        ))
            cptr.free(cptr.ldPtro2(
                gs,
                which_set,
                $sizeof_symsetentry,
                $instance_globals_s_symset + $symsetentry_name
            ));
        cptr.stPtro2(
            gs,
            which_set,
            $sizeof_symsetentry,
            $instance_globals_s_symset + $symsetentry_name,
            null
        );
    }
    /* if 'which_set' was using UTF8, it isn't anymore; if the other set
       isn't using UTF8, discard the data for that */
    if (old_handling == NHC.H_UTF8 &&
            cptr.ldI32o2(
                gs,
                other_set,
                $sizeof_symsetentry,
                $instance_globals_s_symset + $symsetentry_handling
            ) !=
                NHC.H_UTF8)
        free_all_glyphmap_u();
    purge_custom_entries(which_set);
    clear_all_glyphmap_colors();
}

/* called from windmain.c */
/** C ref: symbols.c:353 — @param {*} handling @param {CLongLong} wincap2 @returns {CInt} */
export function symset_is_compatible(handling, wincap2) {
    if (handling == NHC.H_UTF8 && ((wincap2 & 131072n) != 131072n))
        return 0;
    return 1;
}

