    let sl;
    let res;
    let which_set;
    let setcount = 0;
    let chosen = -2;
    let defindx = 0;
    let clr = NHM.NO_COLOR;

    which_set = rogueflag ? NHC.ROGUESET : NHC.PRIMARYSET;
    cptr.stPtro(gs, $instance_globals_s_symset_list, null);
