            /* check restrictions */
            if (rogueflag
                    ? (cptr.ldI32o(sl, $symsetentry_primary) & 1) | 0
                    : (cptr.ldI32o(sl, $symsetentry_rogue) & 1) | 0)
                continue;
            if (cptr.ldI32o(sl, $symsetentry_handling) == NHC.H_MAC)
                continue;
